19	import java.io.IOException;
20	import java.io.UncheckedIOException;
21	import java.nio.charset.StandardCharsets;
22	import java.nio.file.Files;
23	import java.nio.file.Path;
24	import java.nio.file.StandardOpenOption;
25	import org.springframework.beans.factory.annotation.Value;
26	import org.springframework.stereotype.Service;
27	import org.springframework.transaction.support.TransactionSynchronization;
28	import org.springframework.transaction.support.TransactionSynchronizationManager;
29	
30	/**
31	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
32	 * so tests can assert side-effects by reading that file — the second test-assertion channel
33	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
34	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
35	 *
36	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
37	 * SYNC) so a test reads the record immediately.
38	 */
39	@Service
40	public class Audit {
41	
42	    private final Path file;
43	
44	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
45	        this.file = Path.of(path);
46	    }
47	
48	    /** Append one audit record. Tests assert the exact line(s) in the file. */
49	    public synchronized void record(String entry) {
50	        try {
51	            Path parent = file.toAbsolutePath().getParent();
52	            if (parent != null) {
53	                Files.createDirectories(parent);
54	            }
55	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
56	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
57	        } catch (IOException e) {
58	            throw new UncheckedIOException(e);
59	        }
60	    }
61	
62	    /**
63	     * Append one audit record once the current transaction commits, so a change that is refused
64	     * or rolled back writes nothing. Outside a transaction the record is appended at once.
65	     */
66	    public void recordOnCommit(String entry) {
67	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
68	            record(entry);
69	            return;
70	        }
71	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
72	            @Override
73	            public void afterCommit() {
74	                record(entry);
75	            }
76	        });
77	    }
78	
79	    /** Truncate the audit file. */
80	    public synchronized void clear() {
81	        try {
82	            Files.deleteIfExists(file);
83	        } catch (IOException e) {
84	            throw new UncheckedIOException(e);
85	        }
86	    }
87	}
