97	/**
98	 * Serve the SPA from static/ with a deep-link fallback: an unknown, non-API path returns
99	 * index.html so a browser refresh on a client route works. OfficeFloor REST routes and Spring
100	 * endpoints are matched first; only unmatched, non-{@code api/} paths fall through to the SPA.
101	 * TODO: confirm the API path prefix used by the OfficeFloor routes ("api/" assumed here).
102	 */
103	@Configuration
104	public class SpaConfig implements WebMvcConfigurer {
105	
106	    @Override
107	    public void addResourceHandlers(ResourceHandlerRegistry registry) {
108	        registry.addResourceHandler("/**")
109	                .addResourceLocations("classpath:/static/")
110	                .resourceChain(true)
111	                .addResolver(new PathResourceResolver() {
112	                    @Override
113	                    protected Resource getResource(String resourcePath, Resource location) throws IOException {
114	                        if (resourcePath.startsWith("api/")) {
115	                            return null; // let the API handle / 404 it
116	                        }
117	                        Resource requested = location.createRelative(resourcePath);
118	                        return (requested.exists() && requested.isReadable())
119	                                ? requested
120	                                : location.createRelative("index.html");
121	                    }
122	                });
123	    }
