453	import net.officefloor.hq.app.sheet.SheetService;
454	import org.springframework.http.HttpStatus;
455	import org.springframework.stereotype.Service;
456	import org.springframework.transaction.annotation.Transactional;
457	import org.springframework.web.server.ResponseStatusException;
458	
459	@Service
460	public class ClaimService {
461	
462	    private final ClaimRepository claims;
463	    private final PersonRepository people;
464	    private final PersonStatementRepository statements;
465	    private final RateRepository rates;
466	    private final SheetService sheets;
467	    private final Audit audit;
468	
469	    /** A statement just taken: the person, their statement summary now, and their claims, newest first. */
470	    public record Statement(Person person, StatementSummary summary, List<Claim> claims) {
471	    }
472	
473	    public ClaimService(ClaimRepository claims, PersonRepository people, PersonStatementRepository statements,
474	            RateRepository rates, SheetService sheets, Audit audit) {
475	        this.claims = claims;
476	        this.people = people;
477	        this.statements = statements;
478	        this.rates = rates;
479	        this.sheets = sheets;
480	        this.audit = audit;
481	    }
482	
483	    @Transactional(readOnly = true)
484	    public List<Claim> list(String sheetId) {
485	        return claims.findBySheetIdOrderByIdDesc(sheetId);
486	    }
487	
488	    /** Add a claim for a person on the sheet; a missing date takes the sheet's today. */
489	    @Transactional
490	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
491	        Person person = people.findByIdAndSheetId(personId, sheetId)
492	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
493	        LocalDate on = date != null ? date : sheets.today(sheetId);
494	        Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, amount, on, noteOf(note)));
495	        record("CLAIM_ADDED", user, person, claim);
496	        return claim;
497	    }
498	
499	    /** Change a claim's amount, date and note; a missing date takes the sheet's today. */
500	    @Transactional
501	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note) {
502	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
503	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
504	        claim.setAmount(amount);
505	        claim.setDate(date != null ? date : sheets.today(sheetId));
506	        claim.setNote(noteOf(note));
507	        claims.flush();
508	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
509	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
510	        record("CLAIM_EDITED", user, person, claim);
511	        return claim;
512	    }
513	
514	    /** Move a claim to a new status; a move its status does not allow is refused (409), as is
515	     *  settling by the user who opened the claim (403). */
516	    @Transactional
517	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus to) {
518	        Claim claim = claims.findForUpdate(id, sheetId)
519	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
520	        if (!claim.getStatus().canMoveTo(to)) {
521	            throw new ResponseStatusException(HttpStatus.CONFLICT,
522	                    "A " + claim.getStatus() + " claim cannot become " + to);
523	        }
524	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
525	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
526	                    "The user who opened a claim cannot settle it");
527	        }
528	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
529	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
530	        // the VOIDED record carries the number the claim had
531	        Integer number = claim.getNumber();
532	        claim.setStatus(to);
533	        if (to == ClaimStatus.OPEN) {
534	            number = sheets.nextClaimNumber(sheetId);
535	            claim.setNumber(number);
536	            claim.setOpenedBy(user);
537	        } else if (to == ClaimStatus.VOID) {
538	            claim.setNumber(null);
539	        } else if (to == ClaimStatus.SETTLED) {
540	            // a claim bound by a statement settles at its bound figure
541	            claim.setSettledDue(claim.isStated() ? claim.getStatedDue() : dueOf(claim, person));
542	        }
543	        claims.flush();
544	        String event = switch (to) {
545	            case OPEN -> "CLAIM_OPENED";
546	            case SETTLED -> "CLAIM_SETTLED";
547	            case VOID -> "CLAIM_VOIDED";
548	            case DRAFT -> throw new IllegalArgumentException("A claim cannot return to DRAFT");
549	        };
550	        if (to == ClaimStatus.SETTLED) {
551	            BigDecimal due = claim.getSettledDue();
552	            record(event, user, person, claim, number, " due=" + (due == null ? "n/a" : due.toPlainString()));
553	        } else {
554	            record(event, user, person, claim, number);
555	        }
556	        return claim;
557	    }
558	
559	    /** Take a statement of a person: record their due-total now, and bind each of their claims
560	     *  that counts (OPEN or SETTLED) to the due it shows now; the others are left unbound. */
561	    @Transactional
562	    public Statement statement(String sheetId, String user, long personId) {
563	        Person person = people.findForUpdate(personId, sheetId)
564	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
565	        LocalDate today = sheets.today(sheetId);
566	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
567	        List<Claim> counted = theirs.stream().filter(ClaimService::counts).toList();
568	        BigDecimal dueTotal = dueTotalOf(counted, person, today);
569	        for (Claim c : theirs) {
570	            if (counts(c)) {
571	                c.bind(shownDueOf(c, person));
572	            } else {
573	                c.unbind();
574	            }
575	        }
576	        claims.flush();
577	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
578	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
579	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
580	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
581	    }
582	
583	    /** Whether a claim counts toward claimed and due totals: only OPEN and SETTLED ones do. */
584	    private static boolean counts(Claim c) {
585	        return c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.SETTLED;
586	    }
587	
588	    /** The due a claim shows: the due fixed when it was settled, else the one a statement bound it
589	     *  to (null: n/a), else its live due. */
590	    private BigDecimal shownDueOf(Claim claim, Person person) {
591	        if (claim.getSettledDue() != null) {
592	            return claim.getSettledDue();
593	        }
594	        return claim.isStated() ? claim.getStatedDue() : dueOf(claim, person);
595	    }
596	
597	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
598	     *  null (n/a) when their grade has no rate in force on the sheet's today, unless a claim keeps
599	     *  a fixed or bound due. */
600	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
601	        boolean kept = counted.stream()
602	                .anyMatch(c -> c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null));
603	        if (rates.findInForce(person.getSheetId(), person.getGrade(), today).isEmpty() && !kept) {
604	            return null;
605	        }
606	        return counted.stream()
607	                .map(c -> shownDueOf(c, person))
608	                .filter(d -> d != null)
609	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
610	    }
611	
612	    /** The claim's amount times its person's grade rate in force on the claim's date, divided by
613	     *  100, rounded half to even; null with no rate in force then. */
614	    private BigDecimal dueOf(Claim claim, Person person) {
615	        return rates.findInForce(claim.getSheetId(), person.getGrade(), claim.getDate())
616	                .map(Rate::getPct)
617	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
618	                .orElse(null);
619	    }
620	
621	    private void record(String event, String user, Person person, Claim claim) {
622	        record(event, user, person, claim, claim.getNumber());
623	    }
624	
625	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
626	    private void record(String event, String user, Person person, Claim claim, Integer number) {
627	        record(event, user, person, claim, number, "");
628	    }
629	
630	    private void record(String event, String user, Person person, Claim claim, Integer number, String extra) {
631	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
632	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
633	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
634	    }
635	
636	    private static String noteOf(String note) {
637	        return note == null ? "" : note.trim();
638	    }
639	}
