642	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID. */
643	public enum ClaimStatus {
644	    DRAFT, OPEN, SETTLED, VOID;
645	
646	    /** Whether a claim in this status may move to the given status. */
647	    public boolean canMoveTo(ClaimStatus to) {
648	        return switch (to) {
649	            case OPEN -> this == DRAFT;
650	            case SETTLED -> this == OPEN;
651	            case VOID -> this == DRAFT || this == OPEN;
652	            case DRAFT -> false;
653	        };
654	    }
655	}
