844	import java.util.List;
845	import java.util.Map;
846	import java.util.stream.Collectors;
847	import net.officefloor.hq.app.Audit;
848	import net.officefloor.hq.app.sheet.SheetService;
849	import org.springframework.dao.DataIntegrityViolationException;
850	import org.springframework.http.HttpStatus;
851	import org.springframework.orm.ObjectOptimisticLockingFailureException;
852	import org.springframework.stereotype.Service;
853	import org.springframework.transaction.annotation.Transactional;
854	import org.springframework.web.server.ResponseStatusException;
855	
856	@Service
857	public class PersonService {
858	
859	    private final PersonRepository people;
860	    private final PersonStatementRepository statements;
861	    private final SheetService sheets;
862	    private final Audit audit;
863	
864	    public PersonService(PersonRepository people, PersonStatementRepository statements, SheetService sheets,
865	            Audit audit) {
866	        this.people = people;
867	        this.statements = statements;
868	        this.sheets = sheets;
869	        this.audit = audit;
870	    }
871	
872	    @Transactional(readOnly = true)
873	    public List<Person> list(String sheetId) {
874	        return people.findBySheetIdOrderByIdAsc(sheetId);
875	    }
876	
877	    @Transactional(readOnly = true)
878	    public Person get(String sheetId, long id) {
879	        return people.findByIdAndSheetId(id, sheetId)
880	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
881	    }
882	
883	    /** Each person's statement summary, by person id; a person with none is missing. */
884	    @Transactional(readOnly = true)
885	    public Map<Long, StatementSummary> statementSummaries(String sheetId) {
886	        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
887	                .collect(Collectors.groupingBy(PersonStatement::getPersonId,
888	                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
889	    }
890	
891	    @Transactional(readOnly = true)
892	    public StatementSummary statementSummary(long personId) {
893	        return StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId));
894	    }
895	
896	    /** Add a person to the sheet (the sheet is created first if it was never loaded). */
897	    @Transactional
898	    public Person add(String sheetId, String user, String name, String grade) {
899	        sheets.load(sheetId, user);
900	        String trimmed = name.trim();
901	        requireUnusedName(sheetId, null, trimmed);
902	        Person person;
903	        try {
904	            person = people.saveAndFlush(new Person(sheetId, trimmed, grade));
905	        } catch (DataIntegrityViolationException e) {
906	            throw nameInUse(); // added by another user at the same moment
907	        }
908	        record("PERSON_ADDED", sheetId, user, person);
909	        return person;
910	    }
911	
912	    /** Save a person; refused when {@code version} (the one the editor loaded) is no longer the stored one. */
913	    @Transactional
914	    public Person update(String sheetId, String user, long id, Long version, String name, String grade) {
915	        Person person = people.findByIdAndSheetId(id, sheetId)
916	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
917	        if (version == null || version != person.getVersion()) {
918	            throw savedByAnother();
919	        }
920	        String trimmed = name.trim();
921	        requireUnusedName(sheetId, id, trimmed);
922	        person.setName(trimmed);
923	        person.setGrade(grade);
924	        try {
925	            people.flush();
926	        } catch (DataIntegrityViolationException e) {
927	            throw nameInUse(); // taken by another user at the same moment
928	        } catch (ObjectOptimisticLockingFailureException e) {
929	            throw savedByAnother(); // saved by another user at the same moment
930	        }
931	        record("PERSON_EDITED", sheetId, user, person);
932	        return person;
933	    }
934	
935	    private void record(String event, String sheetId, String user, Person person) {
936	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
937	                + " name=" + person.getName() + " grade=" + person.getGrade());
938	    }
939	
940	    /** Refuse a name another person on the sheet already has (ignoring case). */
941	    private void requireUnusedName(String sheetId, Long exceptId, String name) {
942	        boolean taken = people.findBySheetIdAndNameIgnoreCase(sheetId, name).stream()
943	                .anyMatch(p -> !p.getId().equals(exceptId));
944	        if (taken) {
945	            throw nameInUse();
946	        }
947	    }
948	
949	    private static ResponseStatusException savedByAnother() {
950	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Saved by someone else since it was loaded");
951	    }
952	
953	    private static ResponseStatusException nameInUse() {
954	        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
955	    }
956	}
